#!/bin/sh
# PreToolUse(Edit|Write): block edits to generated, secret or tool-owned files.
# Exit 2 is blocking and the message is shown to Claude.
ROOT="$(git rev-parse --show-toplevel 2>/dev/null)" || exit 0
FILE="$(cat - 2>/dev/null | sed -n 's/.*"file_path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -1)"
[ -z "$FILE" ] && exit 0

deny() { echo "guard-paths: refusing to edit $1 — $2" >&2; exit 2; }

case "$FILE" in
  */convex/_generated/*)      deny "$FILE" "generated by Convex; change the schema or functions instead" ;;
  */src/routeTree.gen.ts)     deny "$FILE" "generated by TanStack Router; add a file under src/routes/ instead" ;;
  */.env|*/.env.*)
    case "$FILE" in
      *.example) ;;  # examples are committed on purpose
      *) deny "$FILE" "secrets are not edited by agents; update env.schema.json / .env.example instead" ;;
    esac ;;
  */package-lock.json)        deny "$FILE" "never hand-edit; run npm install and commit the result" ;;
  */.claude/skills/*)         deny "$FILE" "owned by 'npx convex ai-files install'; edits are overwritten" ;;
  */.output/*|*/.tanstack/*|*/.nitro/*|*/.vinxi/*) deny "$FILE" "build output" ;;
esac
exit 0
